#define GFS_CURVED_TRANSFER_LIBRARY
#include "test_curved_transfer_v1.cpp"
#include "material_curved_events.h"
#include "material_curved_topology.h"
static curved::Packet lens_packet(){
    curved::Packet p={};p.parameters[1]=5./3;p.parameters[2]=1e-3;p.parameters[3]=2;p.parameters[4]=2;p.parameters[5]=8;p.parameters[6]=1;p.parameters[7]=1e-6;p.parameters[8]=.25;p.parameters[9]=0;p.cells=1;p.record.resize(1);auto &r=p.record[0];r.cell=102;r.component=0;r.map.n=12;r.scale[0]=r.scale[1]=1;r.triangle.geometry.x[0][0]=r.triangle.geometry.x[0][1]=0;r.triangle.geometry.x[1][0]=1;r.triangle.geometry.x[1][1]=0;r.triangle.geometry.x[2][0]=0;r.triangle.geometry.x[2][1]=1;need(gfs_material_triangle_init(&r.triangle.geometry),"same positive manufactured source triangle");
    for(int a=0;a<10;a++){double x[2];gfs_material_p3_node(&r.triangle,a,x);r.map.x[0][a]=x[0]+.05*x[1]*x[1];r.map.x[1][a]=x[1];r.map.v[0][a]=.1;r.map.v[1][a]=.2;double Dq[4];need(gfs_material_p3_radial_remainder(r.triangle.geometry.x[0],x[0],x[1],p.parameters[3],r.triangle.remainder[a],Dq),"unchanged lens initial basis domain");}return p;
}
struct EventRow {uint64_t triangle=0,evaluations=0,events=0,budget_failures=0,uncertainty_limited=0,panels=0;R event_mass=0,event_K=0,mass_allow=0,K_allow=0,angular_mass=0,angular_K=0;Moment target[24];int complete=0,source_index=0;};
static EventRow event_integrate(size_t it,const curved::Packet &p,const std::vector<curved_partition::Site> &site,const std::vector<R> &weight,const char *dest,bool integration){
    const auto &r=p.record[it];curved_bounds::Tri tri;for(int a=0;a<3;a++)for(int k=0;k<2;k++)tri[a][k]=r.triangle.geometry.x[a][k];auto bound=positive_source_bounds(r,tri,p.parameters[3]);curved_events::Context context(r,p.parameters[3],site,weight,bound.native_position_envelope,bound.native_gradient_envelope);auto events=curved_events::isolate(context);auto bands=curved_events::bands(events);auto base_cuts=radial_cuts(r);std::vector<R> cuts=base_cuts;
    EventRow row;row.triangle=it;row.evaluations=events.evaluations;row.events=events.event.size();row.budget_failures=events.budget_failures;row.uncertainty_limited=events.uncertainty_limited;for(int j=0;j<(int)site.size();j++)if(site[j].id==r.cell)row.source_index=j;
    R minimum=base_cuts.front(),maximum=base_cuts.back(),Ulower=p.parameters[2]*r.triangle.geometry.area*powl(bound.J.hi,1-p.parameters[1])/(p.parameters[1]-1),v2=0;row.mass_allow=1e-12L*p.parameters[6]*r.triangle.geometry.area;row.K_allow=1e-9L*Ulower;for(int k=0;k<2;k++)v2+=curved_bounds::absmax(bound.velocity[k])*curved_bounds::absmax(bound.velocity[k]);
    for(auto band:bands){R lo=std::max(minimum,band.lo),hi=std::min(maximum,band.hi);if(lo>hi)continue;cuts.push_back(lo);cuts.push_back(hi);if(lo==hi)continue;
        /* Root order can change only at the exhaustively enclosed events.
         * Within their radial boxes, retain the unresolved angular windows
         * from the original interval branch guard. A regular simple moving
         * branch is a resolved boundary, not unknown topology. */
        R eventM=0,eventK=0;if(hi<128*LDBL_EPSILON){R measure=curved_bounds::up(acosl(-1.L)*(hi-lo)*(hi+lo));eventM=measure*curved_topology::density_upper(p,lo,hi);eventK=eventM*v2/2;}
        else{auto event_panel=curved_topology::panel(r,p,lo,hi,0,site,weight,bound,&context.map);eventM=event_panel.mass_bound;eventK=event_panel.K_bound;}
        row.event_mass=curved_bounds::up(row.event_mass+eventM);row.event_K=curved_bounds::up(row.event_K+eventK);}
    char path[1024];snprintf(path,sizeof(path),"%s/events_triangle%zu.csv",dest,it);FILE *f=fopen(path,"w");need(f,"new isolated-event witness ledger");fprintf(f,"kind,i,j,k,xlo,xhi,ylo,yhi,rlo,rhi,depth\n");for(auto e:events.event)fprintf(f,"%d,%d,%d,%d,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%d\n",e.kind,e.i,e.j,e.k,e.box.x[0].lo,e.box.x[0].hi,e.box.x[1].lo,e.box.x[1].hi,e.radius.lo,e.radius.hi,e.box.depth);fclose(f);
    std::sort(cuts.begin(),cuts.end());cuts.erase(std::unique(cuts.begin(),cuts.end()),cuts.end());row.panels=cuts.size()-1;
    if(integration){auto q=integrate(it,p,site,weight,16,16,nullptr,&cuts,&bound);for(int j=0;j<(int)site.size();j++)row.target[j]=q.target[j];row.angular_mass=q.angular_uncertainty.a[MASS];row.angular_K=q.angular_uncertainty.a[KINETIC];row.budget_failures+=q.budget_failures;}
    row.complete=events.complete && row.budget_failures==0 && row.event_mass<=row.mass_allow && row.event_K<=row.K_allow;return row;
}
int main(int argc,char **argv){
    int provided;MPI_Init_thread(&argc,&argv,MPI_THREAD_FUNNELED,&provided);active_mpi=true;need(provided>=MPI_THREAD_FUNNELED,"MPI FUNNELED");int rank,ranks;MPI_Comm_rank(MPI_COMM_WORLD,&rank);MPI_Comm_size(MPI_COMM_WORLD,&ranks);need(argc==3 || argc==6,"new output, lens OR actual packet/sites/weighted");auto started=std::chrono::steady_clock::now();bool lens=std::string(argv[2])=="lens";need(!lens || ranks==1,"single isolated lens fixture");curved::Packet p;std::vector<curved_partition::Site> site;std::vector<R> weight;R exact=0,coarse_area=0;
    if(lens){p=lens_packet();R ax=.31L+.05L*.27L*.27L,ay=.27L,delta=1e-4L,d=.1L,root3=sqrtl(3.L);site={{101,ax,ay},{102,ax+d,ay},{103,ax-d/2,ay+d*root3/2},{104,ax-d/2,ay-d*root3/2}};weight={0,d*d-2*d*delta,d*d-2*d*delta,d*d-2*d*delta};exact=3*root3*delta*delta;auto coarse=integrate(0,p,site,weight,12,10,nullptr);coarse_area=coarse.target[0].a[VOLUME];}
    else{need(argc==6 && std::string(argv[2])=="actual","preserved actual curved packet mode");p=curved::read(argv[3]);site=curved_partition::read_sites(argv[4]);weight.resize(site.size());if(atoi(argv[5]))for(size_t j=0;j<site.size();j++)weight[j]=1e-7L*sinl(.7L*j);}
    if(rank==0){std::string path=std::string(argv[1])+"/site_weights.csv";FILE *f=fopen(path.c_str(),"w");need(f,"frozen actual target weights");fprintf(f,"id,weight\n");for(size_t j=0;j<site.size();j++)fprintf(f,"%llu,%.21Lg\n",(unsigned long long)site[j].id,weight[j]);fclose(f);}
    std::vector<EventRow> rows(p.record.size());
    #pragma omp parallel for schedule(dynamic,1)
    for(int it=0;it<(int)p.record.size();it++)if(it%ranks==rank)rows[it]=event_integrate(it,p,site,weight,argv[1],lens);
    std::vector<EventRow> all(rank==0?rows.size()*ranks:0);MPI_Gather(rows.data(),rows.size()*sizeof(EventRow),MPI_BYTE,all.data(),rows.size()*sizeof(EventRow),MPI_BYTE,0,MPI_COMM_WORLD);bool pass=true;
    if(rank==0){for(size_t i=0;i<rows.size();i++)rows[i]=all[(i%ranks)*rows.size()+i];uint64_t evaluations=0,events=0,failures=0,limited=0,passed=0;R M=0,K=0,maxM=0,maxK=0;for(auto r:rows){evaluations+=r.evaluations;events+=r.events;failures+=r.budget_failures;limited+=r.uncertainty_limited;passed+=r.complete;M+=r.event_mass;K+=r.event_K;maxM=std::max(maxM,r.event_mass/r.mass_allow);maxK=std::max(maxK,r.event_K/r.K_allow);}pass=passed==rows.size();R area=lens?rows[0].target[0].a[VOLUME]:0,error=lens?fabsl(area-exact):0;if(lens)pass=pass && coarse_area<.1L*exact && area>.9L*exact && error<1e-11L;
        std::string path=std::string(argv[1])+"/event_rows.csv";FILE *f=fopen(path.c_str(),"w");need(f,"event row ledger");fprintf(f,"triangle,source_index,evaluations,events,budget_failures,uncertainty_limited,radial_panels,event_mass,event_K,mass_allow,K_allow,angular_mass,angular_K,complete\n");for(auto r:rows)fprintf(f,"%llu,%d,%llu,%llu,%llu,%llu,%llu,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%d\n",(unsigned long long)r.triangle,r.source_index,(unsigned long long)r.evaluations,(unsigned long long)r.events,(unsigned long long)r.budget_failures,(unsigned long long)r.uncertainty_limited,(unsigned long long)r.panels,r.event_mass,r.event_K,r.mass_allow,r.K_allow,r.angular_mass,r.angular_K,r.complete);fclose(f);
        double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count();printf("{\"scope\":\"explicit interval isolation of source/plane intersections, active power vertices, radial tangencies and chart crossings of the unchanged actual map; event-only upper bounds; no weight solve/compression/time evolution\",\"lens_fixture\":%s,\"triangles\":%zu,\"ranks\":%d,\"OMP_threads\":%d,\"evaluations\":%llu,\"events\":%llu,\"budget_failures\":%llu,\"uncertainty_limited_boxes\":%llu,\"passed_rows\":%llu,\"event_mass_bound\":%.17Lg,\"event_K_bound\":%.17Lg,\"max_mass_ratio\":%.17Lg,\"max_K_ratio\":%.17Lg,\"exact_area\":%.17Lg,\"coarse_area\":%.17Lg,\"event_partition_area\":%.17Lg,\"absolute_area_error\":%.17Lg,\"all_event_and_fixture_gates_pass\":%s,\"seconds\":%.17g}\n",lens?"true":"false",rows.size(),ranks,omp_get_max_threads(),(unsigned long long)evaluations,(unsigned long long)events,(unsigned long long)failures,(unsigned long long)limited,(unsigned long long)passed,M,K,maxM,maxK,exact,coarse_area,area,error,pass?"true":"false",seconds);
    }int flag=pass?1:0;MPI_Bcast(&flag,1,MPI_INT,0,MPI_COMM_WORLD);active_mpi=false;MPI_Finalize();return flag?0:2;
}
